<script setup lang="ts">
import { computed,ref } from 'vue'
import { fallItems,fallMeasures,fallNotes,circulationDocuments,mobilityGroups,reviewKey,fallSummary,mobilitySummary } from '@/utils/care-review-forms'
import { rehabForms } from '@/utils/rehab-forms'
import type { CareReviewData } from '@/utils/care-review-forms'
const props=defineProps<{modelValue:CareReviewData;formId:string;readonly?:boolean}>()
const emit=defineEmits<{(e:'update:modelValue',value:CareReviewData):void}>()
const activeFall=ref(0)
const scalar=(key:string)=>typeof props.modelValue.values[key]==='string'?props.modelValue.values[key] as string:''
function set(key:string,value:string|string[]){if(!props.readonly)emit('update:modelValue',{...props.modelValue,values:{...props.modelValue.values,[key]:value}})}
function selected(key:string,value:string){const list=props.modelValue.values[key];return Array.isArray(list)&&list.includes(value)}
function toggle(key:string,value:string,on:unknown){const v=props.modelValue.values[key];const list=Array.isArray(v)?v:[];set(key,on?[...new Set([...list,value])]:list.filter(i=>i!==value))}
const fall=computed(()=>fallSummary(props.modelValue.values,activeFall.value))
function addCirculation(){if(!props.readonly)emit('update:modelValue',{...props.modelValue,circulation:[...props.modelValue.circulation,{id:crypto.randomUUID(),date:'',staff:'',signature:'',remarks:''}]})}
function editRow(id:string,key:'date'|'staff'|'signature'|'remarks',value:string){if(!props.readonly)emit('update:modelValue',{...props.modelValue,circulation:props.modelValue.circulation.map(r=>r.id===id?{...r,[key]:value}:r)})}
function removeRow(id:string){if(!props.readonly)emit('update:modelValue',{...props.modelValue,circulation:props.modelValue.circulation.filter(r=>r.id!==id)})}
const guidance=(id:string)=>rehabForms['form-7'].flatMap(s=>s.tables||[]).find(t=>t.id===id)?.guidance||''
</script>
<template>
 <div class="review-fields mt-6">
  <section class="review-section"><h5 class="text-h5 mb-4">{{formId==='form-12'?'個案及傳閱資料':'院友資料'}}</h5><VRow>
   <template v-if="formId!=='form-12'"><VCol cols="12" md="6"><AppTextField :model-value="scalar('age')" label="年齡" type="number" min="0" step="1" :readonly="props.readonly" @update:model-value="set('age',String($event))" /></VCol><VCol cols="12" md="6"><AppSelect :model-value="scalar('gender')" label="性別" :items="['男','女','其他','未提供']" :readonly="props.readonly" @update:model-value="set('gender',$event)" /></VCol><VCol v-if="formId==='form-10'" cols="12"><AppTextField :model-value="scalar('room')" label="房／床號" :readonly="props.readonly" @update:model-value="set('room',$event)" /></VCol></template>
   <VCol v-else cols="12"><AppTextField :model-value="scalar('manager')" label="個案經理" :readonly="props.readonly" @update:model-value="set('manager',$event)" /></VCol>
  </VRow></section>
  <template v-if="formId==='form-10'">
   <section class="review-section"><h5 class="text-h5 mb-2">Morse Fall Scale (Modified)</h5><p class="text-body-2 mb-5">長者跌倒風險評估表及防跌護理措施</p><AppSelect v-model="activeFall" :items="Array.from({length:6},(_,i)=>({title:`第 ${i+1} 次評估`,value:i}))" label="選擇評估紀錄" class="mb-6" />
    <VRow><VCol cols="12" md="6"><AppTextField :model-value="scalar(reviewKey('fall',activeFall,'date'))" label="評估日期" type="date" :readonly="props.readonly" @update:model-value="set(reviewKey('fall',activeFall,'date'),$event)" /></VCol><VCol cols="12" md="6"><AppSelect :model-value="scalar(reviewKey('fall',activeFall,'reason'))" label="評估原因" :items="['A 新入服務','B 跌倒後','C 身體狀況轉變','D 照顧計劃評估']" :readonly="props.readonly" @update:model-value="set(reviewKey('fall',activeFall,'reason'),$event)" /></VCol></VRow>
    <div v-for="item in fallItems" :key="item.key" class="my-5"><AppSelect :model-value="scalar(reviewKey('fall',activeFall,item.key))" :label="item.label" :items="item.options.map(o=>({title:`${o.title}（${o.value} 分）`,value:o.value}))" clearable :readonly="props.readonly" @update:model-value="set(reviewKey('fall',activeFall,item.key),String($event??''))" /></div>
    <div class="d-flex justify-space-between flex-wrap gap-3" aria-live="polite"><strong>{{fall.complete?'總分':'暫計分數'}}：{{fall.score}}</strong><span>已填 {{fall.answered}} / 6 項 · 跌倒危險：{{fall.risk}}</span></div><p class="text-body-2 mt-4">輕度：&lt;45；中度：≥45 至 &lt;80；高度：≥80。</p><details class="mt-4"><summary>原表評分註解</summary><p class="source-notes mt-3">{{fallNotes}}</p></details>
   </section>
   <section class="review-section"><h5 class="text-h5 mb-4">第 {{activeFall+1}} 次評估：預防跌倒之護理措施</h5><VCheckbox v-for="(measure,index) in fallMeasures" :key="index" :model-value="selected(reviewKey('fall',activeFall,'measures'),String(index+1))" :label="`${index+1}. ${measure}`" :readonly="props.readonly" hide-details @update:model-value="toggle(reviewKey('fall',activeFall,'measures'),String(index+1),$event)" /><p class="text-body-2 mt-4">原表護理分組：輕度第 1–12 項；中度第 1–19 項；高度第 1–22 項。</p><VRow class="mt-4"><VCol cols="12" md="6"><AppTextField :model-value="scalar(reviewKey('fall',activeFall,'staff'))" label="評估職員姓名" :readonly="props.readonly" @update:model-value="set(reviewKey('fall',activeFall,'staff'),$event)" /></VCol><VCol cols="12" md="6"><AppTextField :model-value="scalar(reviewKey('fall',activeFall,'title'))" label="職銜" :readonly="props.readonly" @update:model-value="set(reviewKey('fall',activeFall,'title'),$event)" /></VCol><VCol cols="12"><AppTextField :model-value="scalar(reviewKey('fall',activeFall,'signature'))" label="簽署（輸入姓名）" :readonly="props.readonly" @update:model-value="set(reviewKey('fall',activeFall,'signature'),$event)" /></VCol></VRow></section>
   <section class="review-section"><h5 class="text-h5 mb-4">六次評估總覽</h5><div class="review-scroll"><table><thead><tr><th>評估</th><th>日期</th><th>分數</th><th>跌倒危險</th></tr></thead><tbody><tr v-for="i in 6" :key="i"><th>{{i}}</th><td>{{scalar(reviewKey('fall',i-1,'date'))||'—'}}</td><td>{{fallSummary(modelValue.values,i-1).complete?fallSummary(modelValue.values,i-1).score:'未完成'}}</td><td>{{fallSummary(modelValue.values,i-1).risk}}</td></tr></tbody></table></div></section>
  </template>
  <template v-else-if="formId==='form-11'">
   <section v-for="group in mobilityGroups" :key="group.id" class="review-section"><h5 class="text-h5 mb-5">{{group.title}}</h5><div class="review-scroll"><table class="mobility-table"><thead><tr><th>項目／日期</th><th v-for="i in 4" :key="i"><AppTextField :model-value="scalar(reviewKey(group.id,i-1,'date'))" type="date" :aria-label="`${group.title} 第 ${i} 次日期`" :readonly="props.readonly" @update:model-value="set(reviewKey(group.id,i-1,'date'),$event)" /></th></tr></thead><tbody><tr v-for="row in group.rows" :key="row.key"><th>{{group.id==='ems'&&row.key==='reach'?'VII. Functional Reach Test (inch)':row.label}}</th><td v-for="i in 4" :key="i"><AppSelect :model-value="scalar(reviewKey(group.id,i-1,row.key))" :items="row.options.map(String)" :aria-label="`${row.label} 第 ${i} 次分數`" clearable :readonly="props.readonly" @update:model-value="set(reviewKey(group.id,i-1,row.key),String($event??''))" /></td></tr><tr><th>總分／暫計分數</th><td v-for="i in 4" :key="i">{{mobilitySummary(modelValue.values,group.id,group.rows,i-1).score}} / {{group.max}}<div class="text-caption">已填 {{mobilitySummary(modelValue.values,group.id,group.rows,i-1).answered}} / {{group.rows.length}}</div></td></tr></tbody></table></div><details class="mt-4"><summary>原表評分說明及參考指標</summary><p class="source-notes mt-3">{{guidance(group.id)}}</p></details></section>
   <section class="review-section"><h5 class="text-h5 mb-4">Tinetti Mobility Score（Balance + Gait）</h5><div class="review-scroll"><table><thead><tr><th>評估</th><th>總分／28</th><th>狀態</th></tr></thead><tbody><tr v-for="i in 4" :key="i"><th>{{i}}</th><td>{{mobilitySummary(modelValue.values,'balance',mobilityGroups[1].rows,i-1).score+mobilitySummary(modelValue.values,'gait',mobilityGroups[2].rows,i-1).score}} / 28</td><td>{{mobilitySummary(modelValue.values,'balance',mobilityGroups[1].rows,i-1).complete&&mobilitySummary(modelValue.values,'gait',mobilityGroups[2].rows,i-1).complete?'已完成':'暫計'}}</td></tr></tbody></table></div></section>
   <section class="review-section"><h5 class="text-h5 mb-4">Ambulation / 步行狀況</h5><AppTextarea :model-value="scalar('ambulatory')" label="Ambulatory State" rows="2" class="mb-5" :readonly="props.readonly" @update:model-value="set('ambulatory',$event)" /><AppTextarea :model-value="scalar('gaitAnalysis')" label="Gait Analysis" rows="2" class="mb-5" :readonly="props.readonly" @update:model-value="set('gaitAnalysis',$event)" /><AppTextarea :model-value="scalar('stairs')" label="Stair Climbing" rows="2" class="mb-5" :readonly="props.readonly" @update:model-value="set('stairs',$event)" /><AppTextField :model-value="scalar('tug')" label="Timed Up and Go Test" class="mb-4" :readonly="props.readonly" @update:model-value="set('tug',$event)" /><p class="text-body-2 mb-5">原表：少於 20 秒傾向可獨立活動；30 秒或以上傾向在多項活動中需要他人協助。</p><AppTextField :model-value="scalar('therapist')" label="Physiotherapist / 物理治療師" :readonly="props.readonly" @update:model-value="set('therapist',$event)" /></section>
  </template>
  <template v-else-if="formId==='form-12'">
   <section class="review-section"><div class="d-flex flex-wrap align-center justify-space-between gap-3 mb-5"><h5 class="text-h5">傳閱紀錄</h5><VBtn v-if="!props.readonly" type="button" variant="tonal" prepend-icon="tabler-plus" @click="addCirculation">新增傳閱紀錄</VBtn></div><p v-if="!modelValue.circulation.length" class="text-center py-5">暫無傳閱紀錄</p><div v-for="(row,index) in modelValue.circulation" :key="row.id" class="circulation-row"><div class="d-flex justify-space-between align-center mb-3"><span>紀錄 {{index+1}}</span><VBtn v-if="!props.readonly" type="button" icon="tabler-trash" color="error" variant="text" size="small" :aria-label="`刪除傳閱紀錄 ${index+1}`" @click="removeRow(row.id)" /></div><VRow><VCol cols="12" md="6"><AppTextField :model-value="row.date" type="date" label="日期" :readonly="props.readonly" @update:model-value="editRow(row.id,'date',$event)" /></VCol><VCol cols="12" md="6"><AppTextField :model-value="row.staff" label="職員姓名" :readonly="props.readonly" @update:model-value="editRow(row.id,'staff',$event)" /></VCol><VCol cols="12"><AppTextField :model-value="row.signature" label="簽署（輸入姓名）" :readonly="props.readonly" @update:model-value="editRow(row.id,'signature',$event)" /></VCol><VCol cols="12"><AppTextarea :model-value="row.remarks" label="備註" rows="2" :readonly="props.readonly" @update:model-value="editRow(row.id,'remarks',$event)" /></VCol></VRow></div></section>
   <section class="review-section"><h5 class="text-h5 mb-4">傳閱文件</h5><VCheckbox v-for="(doc,index) in circulationDocuments" :key="index" :model-value="selected('documents',String(index+1))" :label="`${index+1}. ${doc}`" :readonly="props.readonly" hide-details @update:model-value="toggle('documents',String(index+1),$event)" /></section><p class="text-body-2 mb-5">因個人私隱條例，請勿隨意翻閱，多謝合作。</p>
  </template>
 </div>
</template>
<style scoped>
.review-section{padding:20px;margin-block:24px;border:1px solid rgba(var(--v-border-color),var(--v-border-opacity));border-radius:6px}
.review-scroll{overflow-x:auto}.review-scroll table{border-collapse:collapse;inline-size:100%;min-inline-size:440px}.review-scroll th,.review-scroll td{padding:12px;border:1px solid rgba(var(--v-border-color),var(--v-border-opacity));text-align:start}.mobility-table th:first-child{min-inline-size:200px}.mobility-table td,.mobility-table th:not(:first-child){min-inline-size:165px}.source-notes{white-space:pre-line;line-height:1.8}.circulation-row{padding-block:18px;border-block-start:1px solid rgba(var(--v-border-color),var(--v-border-opacity))}.review-fields :deep(.v-label){white-space:normal;opacity:1}
@media(max-width:600px){.review-section{padding:14px}}
</style>
